<?php
session_start(); include('dbstring.php'); include('check-login.php'); include_once('academic-plan-utils.php'); academic_plan_ensure_table($con);
$canManageAcademicPlan = (isset($_SESSION['ACCESSLEVEL']) && $_SESSION['ACCESSLEVEL'] === 'administrator') || (isset($_SESSION['ACCESSLEVEL'], $_SESSION['SYSTEMTYPE']) && $_SESSION['ACCESSLEVEL'] === 'user' && $_SESSION['SYSTEMTYPE'] === 'AssistantHeadAdministration');
if(!$canManageAcademicPlan){ header('location:academic-plan-view.php'); exit(); }
$message='';
if(isset($_POST['save_plan']) && trim((string)(isset($_POST['planid']) ? $_POST['planid'] : ''))===''){
    $planId=academic_plan_id(); $title=trim((string)$_POST['title']); $type=trim((string)$_POST['eventtype']); if($type===''){$type='Academic Activity';} $start=trim((string)$_POST['startdate']); $end=trim((string)$_POST['enddate']); $description=trim((string)$_POST['description']); $batch=trim((string)$_POST['batchid']); $term=trim((string)$_POST['termname']); $week=(int)(isset($_POST['weeknumber']) ? $_POST['weeknumber'] : 0); $audience=in_array(isset($_POST['audience']) ? $_POST['audience'] : '',academic_plan_audiences(),true) ? $_POST['audience'] : 'All School'; $classid=trim((string)(isset($_POST['classid']) ? $_POST['classid'] : '')); $venue=trim((string)(isset($_POST['venue']) ? $_POST['venue'] : '')); $owner=trim((string)(isset($_POST['activityowner']) ? $_POST['activityowner'] : '')); $versionnote=trim((string)(isset($_POST['versionnote']) ? $_POST['versionnote'] : ''));
    if($title==='' || $start===''){ $message='Please enter an activity title and start date.'; }else{ $stmt=mysqli_prepare($con,'INSERT INTO tblacademicplan(planid,title,eventtype,startdate,enddate,description,batchid,termname,weeknumber,audience,classid,venue,activityowner,versionnote,status,recordedby) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)'); $status='draft'; $by=$_SESSION['USERID']; mysqli_stmt_bind_param($stmt,'ssssssssssssssss',$planId,$title,$type,$start,$end,$description,$batch,$term,$week,$audience,$classid,$venue,$owner,$versionnote,$status,$by); $message=mysqli_stmt_execute($stmt)?'Activity saved as a draft. Add the rest of the semester plan, then publish them together.':'The activity could not be saved.'; mysqli_stmt_close($stmt); }
}
if(isset($_POST['save_plan']) && trim((string)(isset($_POST['planid']) ? $_POST['planid'] : ''))!==''){
    $planId=mysqli_real_escape_string($con,trim((string)$_POST['planid'])); $title=trim((string)$_POST['title']); $type=trim((string)$_POST['eventtype']); $start=trim((string)$_POST['startdate']); $end=trim((string)$_POST['enddate']); $description=trim((string)$_POST['description']); $batch=trim((string)$_POST['batchid']); $term=trim((string)$_POST['termname']); $week=(int)(isset($_POST['weeknumber']) ? $_POST['weeknumber'] : 0);
    if($title==='' || $start===''){ $message='Please enter an activity title and start date.'; }else{ $stmt=mysqli_prepare($con,'UPDATE tblacademicplan SET title=?,eventtype=?,startdate=?,enddate=?,description=?,batchid=?,termname=?,weeknumber=? WHERE planid=?'); mysqli_stmt_bind_param($stmt,'sssssssis',$title,$type,$start,$end,$description,$batch,$term,$week,$planId); $message=mysqli_stmt_execute($stmt)?'Academic-plan activity updated.':'The activity could not be updated.'; mysqli_stmt_close($stmt); }
}
if(isset($_POST['publish_drafts'])){
    $_Published=mysqli_query($con,"UPDATE tblacademicplan SET status='published' WHERE status='draft'");
    $message=$_Published ? 'All draft academic-plan activities have been published for teachers and students.' : 'The draft plan could not be published.';
}
if(isset($_POST['save_plan']) || isset($_POST['publish_drafts'])){
    $_SESSION['ACADEMIC_PLAN_MESSAGE']=$message;
    header('location:academic-plan.php');
    exit();
}
if(isset($_SESSION['ACADEMIC_PLAN_MESSAGE'])){
    $message=$_SESSION['ACADEMIC_PLAN_MESSAGE'];
    unset($_SESSION['ACADEMIC_PLAN_MESSAGE']);
}
if(isset($_GET['delete']) && $_GET['delete']!==''){ $id=mysqli_real_escape_string($con,$_GET['delete']); mysqli_query($con,"DELETE FROM tblacademicplan WHERE planid='$id'"); header('location:academic-plan.php'); exit(); }
$batches=array(); $br=mysqli_query($con,'SELECT batchid,batch FROM tblbatch ORDER BY datetimeentry DESC'); if($br){while($r=mysqli_fetch_array($br,MYSQLI_ASSOC)){$batches[]=$r;}} $rows=academic_plan_rows($con,'',true);
?>
<!DOCTYPE html><html><head><?php include('links.php'); ?><link rel="stylesheet" href="css/academic-plan.css"><link rel="stylesheet" href="css/academic-plan-form.css"><link rel="stylesheet" href="css/academic-plan-workflow.css"><link rel="stylesheet" href="css/academic-plan-table.css"></head><body class="academic-plan-page"><div class="header"><?php include('menu.php'); ?></div><main class="academic-plan-shell"><section class="academic-plan-hero"><div><span>ACADEMIC ADMINISTRATION</span><h1>Build the Semester Plan</h1><p>Add every activity as a draft first. When the full term itinerary is ready, publish the complete plan once for teachers and students.</p></div><div class="academic-plan-hero-card"><i class="fa fa-map-signs"></i><strong>One school roadmap</strong><small>Plan first. Publish together.</small></div></section>
<?php if($message!==''){ ?><div class="academic-plan-message"><?php echo academic_plan_escape($message); ?></div><?php } ?>
<div class="academic-plan-admin-layout"><section class="academic-plan-form-card"><h2>Add an academic activity</h2><p class="academic-plan-form-note">Each activity is saved privately as a draft. Add the full list before publishing the plan.</p><form method="post"><label>Activity title</label><input name="title" required placeholder="e.g. Mid-Semester Examinations begin"><label>Activity type</label><input name="eventtype" required placeholder="e.g. Academic, Examination, Holiday, Meeting"><div class="academic-plan-form-grid"><div><label>Start date</label><input type="date" name="startdate" required></div><div><label>End date <small>(optional)</small></label><input type="date" name="enddate"></div></div><label>Academic year / batch</label><select name="batchid"><option value="">All academic years</option><?php foreach($batches as $batch){ ?><option value="<?php echo academic_plan_escape($batch['batchid']); ?>"><?php echo academic_plan_escape($batch['batch']); ?></option><?php } ?></select><label>Semester</label><select name="termname"><option value="">All semesters</option><option value="1">Semester 1</option><option value="2">Semester 2</option></select><label>Details</label><textarea name="description" placeholder="What should teachers and students prepare for?"></textarea><button name="save_plan"><i class="fa fa-plus"></i> Add to Draft Plan</button></form></section><section class="academic-plan-admin-list"><div class="academic-plan-board-head"><div><span>Semester plan</span><h2>All planned activities</h2></div><div class="academic-plan-list-actions"><a href="academic-plan-view.php">View as users do</a><form method="post"><button class="academic-plan-publish-btn" name="publish_drafts" onclick="return confirm('Publish all draft activities now?')"><i class="fa fa-bullhorn"></i> Publish Draft Plan</button></form></div></div><?php if(count($rows)>0){ ?><div class="academic-plan-table-wrap"><table class="academic-plan-table"><thead><tr><th>Start Date</th><th>End Date</th><th>Activity</th><th>Activity Type</th><th>Semester</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $row){ ?><tr><td><strong><?php echo date('d M Y',strtotime($row['startdate'])); ?></strong></td><td><?php echo trim((string)$row['enddate'])!=='' ? academic_plan_escape(date('d M Y',strtotime($row['enddate']))) : 'One day'; ?></td><td><strong><?php echo academic_plan_escape($row['title']); ?></strong><?php if(trim((string)$row['description'])!==''){ ?><small><?php echo academic_plan_escape($row['description']); ?></small><?php } ?></td><td><span class="academic-plan-type"><?php echo academic_plan_escape($row['eventtype']); ?></span></td><td><?php echo trim((string)$row['termname'])!=='' ? 'Semester '.academic_plan_escape($row['termname']) : 'All semesters'; ?></td><td><span class="academic-plan-status academic-plan-status--<?php echo academic_plan_escape($row['status']); ?>"><?php echo academic_plan_escape($row['status']); ?></span></td><td><a class="academic-plan-delete" href="academic-plan.php?delete=<?php echo rawurlencode($row['planid']); ?>" onclick="return confirm('Remove this activity?')">Remove</a></td></tr><?php } ?></tbody></table></div><?php }else{ ?><div class="academic-plan-empty">Start by adding all the activities for the term. They will remain private drafts until you publish the plan.</div><?php } ?></section></div></main></body></html>
